export interface ProtectedTranslationText {
  text: string;
  citations: string[];
  links: ProtectedTranslationLink[];
  formats: ProtectedTranslationFormat[];
  htmlTags: string[];
  codeBlocks: string[];
  codeBlockSlots?: ProtectedCodeBlockSlot[];
  paragraphBreaks: string[];
  sourceLineMarkers?: SourceLineMarker[];
}

interface ProtectedCodeBlockSlot {
  lineIndex: number;
  beforeParagraphBreaks: number;
  afterParagraphBreaks: number;
}

type SourceLineMarker =
  | "ordered"
  | "unordered"
  | "quote"
  | "heading"
  | "code"
  | null;

interface ProtectedTranslationLink {
  href: string;
  text: string;
}

interface ProtectedTranslationFormat {
  tag: "sup" | "sub";
  text: string;
}

export function chunkItems<T>(items: T[], size: number): T[][] {
  const chunkSize = Math.max(1, Math.round(size));
  const chunks: T[][] = [];
  for (let index = 0; index < items.length; index += chunkSize) {
    chunks.push(items.slice(index, index + chunkSize));
  }
  return chunks;
}

export async function mapWithConcurrency<T, R>(
  items: T[],
  limit: number,
  worker: (item: T, index: number) => Promise<R>
): Promise<R[]> {
  const concurrency = Math.max(1, Math.min(items.length, Math.round(limit)));
  const results: R[] = new Array(items.length);
  let nextIndex = 0;
  await Promise.all(
    Array.from({ length: concurrency }, async () => {
      while (nextIndex < items.length) {
        const index = nextIndex;
        nextIndex += 1;
        results[index] = await worker(items[index], index);
      }
    })
  );
  return results;
}

const TRANSLATION_CITATION_PATTERN =
  /\[\s*\d+(?:\s*[-,–—]\s*\d+)*\s*\]|[¹²³⁴⁵⁶⁷⁸⁹⁰]+/g;

type ProtectedTokenKind =
  | "CITATION"
  | "PARAGRAPH_BREAK"
  | "LINK_START"
  | "LINK_END"
  | "FORMAT_START"
  | "FORMAT_END"
  | "HTML_TAG"
  | "CODE_BLOCK";

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function protectedTokenPattern(
  kind: ProtectedTokenKind,
  index: number
) {
  return new RegExp(
    protectedTokenSource(kind, index),
    "gi"
  );
}

function protectedTokenSource(
  kind: ProtectedTokenKind,
  index: number
): string {
  const token = `WEBMIND_${kind}_${index}(?!\\d)`;
  const backtickWrapper = "`{0,3}";
  return `${backtickWrapper}(?:\\{\\{\\s*${token}\\s*\\}\\}|\\[\\s*${token}\\s*\\]|${token})${backtickWrapper}`;
}

function protectFencedCodeBlocks(
  text: string,
  codeBlocks: string[],
  codeBlockSlots: ProtectedCodeBlockSlot[]
): string {
  const lines = text.split("\n");
  const protectedLines: string[] = [];
  for (let index = 0; index < lines.length;) {
    const opening = lines[index].match(/^ {0,3}(`{3,}|~{3,})(.*)$/);
    if (!opening || (opening[1][0] === "`" && opening[2].includes("`"))) {
      protectedLines.push(lines[index]);
      index += 1;
      continue;
    }
    const marker = opening[1][0];
    const minimumLength = opening[1].length;
    let closingIndex = index + 1;
    for (; closingIndex < lines.length; closingIndex += 1) {
      const closing = lines[closingIndex].match(/^ {0,3}(`+|~+)[\t ]*$/);
      if (
        closing &&
        closing[1][0] === marker &&
        closing[1].length >= minimumLength
      ) {
        break;
      }
    }
    if (closingIndex >= lines.length) {
      protectedLines.push(lines[index]);
      index += 1;
      continue;
    }
    codeBlocks.push(lines.slice(index, closingIndex + 1).join("\n"));
    codeBlockSlots.push({
      lineIndex: protectedLines.length,
      beforeParagraphBreaks: 0,
      afterParagraphBreaks: 0
    });
    protectedLines.push(`{{WEBMIND_CODE_BLOCK_${codeBlocks.length}}}`);
    index = closingIndex + 1;
  }
  return protectedLines.join("\n");
}

function visibleTextFromHtmlFragment(value: string): string {
  return value
    .replace(/<script\b[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const BRACKET_CITATION_MARKER_SOURCE =
  "\\[\\s*\\d+(?:\\s*[-,–—]\\s*\\d+)*\\s*\\]";

const CITATION_EXPLANATION_BEFORE_MARKER_PATTERN = new RegExp(
  [
    "(^|[\\s([{（【「『“‘\\]])",
    "(?:\\*\\*\\s*)?",
    "(?:",
    "\\d+\\s+(?:citations?|references?)\\s+(?:from\\s+)?(?:multiple|several|various|many)\\s+(?:sources?|references?|outlets?)",
    "|(?:citations?|references?|sources?)\\s+\\d+\\s+(?:from|based\\s+on)\\s+[^\\[\\]\\n*]{1,80}?",
    ")",
    "(?:\\s*\\*\\*)?",
    "\\s*",
    `(${BRACKET_CITATION_MARKER_SOURCE})`
  ].join(""),
  "gi"
);

export function cleanCitationExplanationText(text: string): string {
  let cleaned = text;
  let previous = "";
  while (cleaned !== previous) {
    previous = cleaned;
    cleaned = cleaned.replace(
      CITATION_EXPLANATION_BEFORE_MARKER_PATTERN,
      "$1$2"
    );
  }
  return cleaned;
}

function stripTranslationTaskPreface(text: string): string {
  let cleaned = text;
  const prefacePattern =
    /^\s*(?:(?:这是(?:一个|一项)?翻译任务[。.!！]?\s*)?(?:以下是(?:根据您提供的内容进行的)?翻译|翻译(?:如下|结果)|译文如下|以下为译文)[：:。.!！]?\s*)+/i;
  while (prefacePattern.test(cleaned)) {
    cleaned = cleaned.replace(prefacePattern, "");
  }
  return cleaned.trimStart();
}

function stripCitationExplanationNoise(
  text: string,
  citationCount: number
): string {
  let cleaned = text;
  for (let index = 1; index <= citationCount; index += 1) {
    const token = protectedTokenSource("CITATION", index);
    const beforeToken = new RegExp(
      [
        "(?:[（(]\\s*)?",
        "(?:(?:该|此|本)?(?:信息|内容|內容|资料|資料|句子|段落)?\\s*)?",
        "(?:(?:来自|來自|源自|based\\s+on|from)\\s*)?",
        "(?:多方|多个|多個|若干|上方|以上|前述|multiple|several)?\\s*",
        "(?:来源|來源|资料来源|資料來源|source|sources)\\s*",
        "(?:的|之)?\\s*",
        "(?:\\d+|[一二三四五六七八九十]+)?\\s*",
        "(?:条|條|处|處|个|個)?\\s*",
        "(?:引用|引文|参考|參考|citation|citations|reference|references)?\\s*",
        "(?:[）)]\\s*)?",
        `(${token})`
      ].join(""),
      "gi"
    );
    const afterToken = new RegExp(
      [
        `(${token})`,
        "\\s*(?:[（(]\\s*)?",
        "(?:(?:该|此|本)?(?:信息|内容|內容|资料|資料)?\\s*)?",
        "(?:来自|來自|源自|来源于|來源於|based\\s+on|from)\\s*",
        "[^。.!?\\n]{0,50}",
        "(?:引用|引文|参考|參考|来源|來源|source|sources|citation|citations|reference|references)",
        "[^。.!?\\n]{0,20}",
        "(?:[）)]\\s*)?"
      ].join(""),
      "gi"
    );
    cleaned = cleaned.replace(beforeToken, "$1").replace(afterToken, "$1");
  }
  return cleaned;
}

function stripCitationMarkerExplanationNoise(
  text: string,
  markers: string[]
): string {
  let cleaned = text;
  markers.forEach((marker, index) => {
    if (!marker) return;
    const markerSource = escapeRegExp(marker);
    const citationNumber = String(index + 1);
    const beforeMarker = new RegExp(
      [
        "(?:\\s|^)",
        "(?:citation|citations|reference|references|source|sources|引用|引文|来源|來源|参考|參考)",
        "\\s*",
        `(?:${citationNumber}|\\d+)?`,
        "\\s*",
        "(?:from|based\\s+on|来自|來自|源自|来源于|來源於|：|:)?",
        "\\s*",
        "[^\\[\\]{}\\n]{0,80}?",
        `(${markerSource})`
      ].join(""),
      "gi"
    );
    const afterMarker = new RegExp(
      [
        `(${markerSource})`,
        "\\s*",
        "(?:citation|citations|reference|references|source|sources|引用|引文|来源|來源|参考|參考)",
        "\\s*",
        `(?:${citationNumber}|\\d+)?`,
        "\\s*",
        "(?:from|based\\s+on|来自|來自|源自|来源于|來源於|：|:)?",
        "\\s*",
        "[^\\[\\]{}\\n]{0,80}"
      ].join(""),
      "gi"
    );
    cleaned = cleaned
      .replace(beforeMarker, "$1")
      .replace(afterMarker, "$1");
  });
  return cleaned;
}

function stripBrokenTranslationPlaceholderFragments(text: string): string {
  return text
    .replace(/\{+\s*WEBMIND_[A-Z0-9_]+\s*\}+/gi, "")
    .replace(/\[\s*WEBMIND_[A-Z0-9_]+\s*\]/gi, "")
    .replace(/WEBMIND_[A-Z0-9_]+/gi, "")
    .replace(/\{+\s*\d+\s*\}+/g, "")
    .replace(/\{+[ \t]*(?=$|[\r\n])/g, "")
    .replace(/(^|[\r\n])[ \t]*\}+/g, "$1")
    .replace(/\[\s*\d+\s*\]/g, (match) => match.trim())
    .replace(/[ \t]{2,}/g, " ");
}

function isIncompleteProtectedTokenBody(value: string): boolean {
  const compact = value.replace(/[\t ]/g, "").toUpperCase();
  if (!compact) return true;
  return (
    "WEBMIND_".startsWith(compact) ||
    (compact.startsWith("WEBMIND_") && /^[A-Z0-9_]+$/.test(compact))
  );
}

function stripIncompleteProtectedTokenSuffix(text: string): string {
  const scanStart = Math.max(0, text.length - 96);
  for (let index = scanStart; index < text.length; index += 1) {
    let remainder = text.slice(index);
    const backticks = remainder.match(/^`{1,3}[\t ]*/)?.[0] ?? "";
    if (backticks) remainder = remainder.slice(backticks.length);
    let hasWrapper = Boolean(backticks);
    if (remainder.startsWith("{{")) {
      remainder = remainder.slice(2);
      hasWrapper = true;
    } else if (remainder.startsWith("{") || remainder.startsWith("[")) {
      remainder = remainder.slice(1);
      hasWrapper = true;
    }
    if (
      hasWrapper &&
      isIncompleteProtectedTokenBody(remainder.trimEnd())
    ) {
      return text.slice(0, index).trimEnd();
    }
  }

  for (let index = text.length - 1; index >= scanStart; index -= 1) {
    if (text[index] !== "W") continue;
    const candidate = text.slice(index).trimEnd();
    if (
      candidate === candidate.toUpperCase() &&
      isIncompleteProtectedTokenBody(candidate)
    ) {
      return text.slice(0, index).trimEnd();
    }
  }
  return text;
}

export function protectTranslationText(text: string): ProtectedTranslationText {
  const citations: string[] = [];
  const links: ProtectedTranslationLink[] = [];
  const formats: ProtectedTranslationFormat[] = [];
  const htmlTags: string[] = [];
  const codeBlocks: string[] = [];
  const codeBlockSlots: ProtectedCodeBlockSlot[] = [];
  const paragraphBreaks: string[] = [];
  const withoutCodeBlocks = protectFencedCodeBlocks(
    text.replace(/\r\n?/g, "\n"),
    codeBlocks,
    codeBlockSlots
  );
  const protectFormat = (tag: "sup" | "sub", value: string) => {
    const visibleText = visibleTextFromHtmlFragment(value);
    if (!visibleText) return "";
    formats.push({ tag, text: visibleText });
    const index = formats.length;
    return `{{WEBMIND_FORMAT_START_${index}}}${visibleText}{{WEBMIND_FORMAT_END_${index}}}`;
  };
  const withFormats = withoutCodeBlocks.replace(
    /<(sup|sub)\b[^>]*>([\s\S]*?)<\/\1>/gi,
    (_match, tag: string, value: string) =>
      protectFormat(tag.toLowerCase() as "sup" | "sub", value)
  );
  const protectLink = (href: string, linkText: string) => {
    const visibleText = visibleTextFromHtmlFragment(linkText);
    if (!href.trim() || !visibleText) return visibleText;
    links.push({ href: href.trim(), text: visibleText });
    const index = links.length;
    return `{{WEBMIND_LINK_START_${index}}}${visibleText}{{WEBMIND_LINK_END_${index}}}`;
  };
  const withHtmlLinks = withFormats.replace(
    /<a\b[^>]*\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>([\s\S]*?)<\/a>/gi,
    (
      _match,
      doubleHref: string | undefined,
      singleHref: string | undefined,
      bareHref: string | undefined,
      label: string
    ) => protectLink(doubleHref ?? singleHref ?? bareHref ?? "", label)
  );
  const withMarkdownLinks = withHtmlLinks.replace(
    /(^|[^!])\[([^\]\n]{1,500})\]\(\s*(?:<([^>\n]+)>|([^\s)]+))(?:\s+(?:"[^"\n]*"|'[^'\n]*'|\([^)\n]*\)))?\s*\)/g,
    (
      _match,
      prefix: string,
      label: string,
      angleHref: string | undefined,
      plainHref: string | undefined
    ) => `${prefix}${protectLink(angleHref ?? plainHref ?? "", label)}`
  );
  const withCitations = withMarkdownLinks.replace(TRANSLATION_CITATION_PATTERN, (marker) => {
    citations.push(marker);
    return `{{WEBMIND_CITATION_${citations.length}}}`;
  });
  const withHtmlTags = withCitations.replace(
    /<\/?[A-Za-z][A-Za-z0-9:-]*(?:\s+[^<>]*?)?\s*\/?>/g,
    (tag) => {
      htmlTags.push(tag);
      return `{{WEBMIND_HTML_TAG_${htmlTags.length}}}`;
    }
  );
  const protectedText = withHtmlTags
    .replace(/\n+/g, (separator) => {
      paragraphBreaks.push(separator.length > 1 ? "\n\n" : "\n");
      return `{{WEBMIND_PARAGRAPH_BREAK_${paragraphBreaks.length}}}`;
    });
  codeBlockSlots.forEach((slot, index) => {
    const token = `{{WEBMIND_CODE_BLOCK_${index + 1}}}`;
    const tokenStart = protectedText.indexOf(token);
    if (tokenStart < 0) return;
    const before = protectedText.slice(0, tokenStart);
    const after = protectedText.slice(tokenStart + token.length);
    slot.beforeParagraphBreaks = Array.from(
      before.matchAll(/\{\{WEBMIND_PARAGRAPH_BREAK_\d+\}\}/g)
    ).length;
    slot.afterParagraphBreaks = /\{\{WEBMIND_PARAGRAPH_BREAK_\d+\}\}/.test(
      after
    )
      ? slot.beforeParagraphBreaks + 1
      : 0;
  });
  return {
    text: protectedText,
    citations,
    links,
    formats,
    htmlTags,
    codeBlocks,
    codeBlockSlots,
    paragraphBreaks,
    sourceLineMarkers: withoutCodeBlocks.split("\n").map(sourceLineMarker)
  };
}

export function scopeProtectedTranslationText(
  protection: ProtectedTranslationText,
  protectedInput: string
): ProtectedTranslationText {
  if (protectedInput === protection.text) return protection;
  return {
    ...protection,
    citations: protection.citations.map((marker, index) =>
      protectedTokenPattern("CITATION", index + 1).test(protectedInput)
        ? marker
        : ""
    ),
    codeBlocks: protection.codeBlocks.map((code, index) =>
      protectedTokenPattern("CODE_BLOCK", index + 1).test(protectedInput)
        ? code
        : ""
    ),
    sourceLineMarkers: undefined
  };
}

function sourceLineMarker(line: string): SourceLineMarker {
  const trimmed = line.trimStart();
  if (trimmed.startsWith("{{WEBMIND_CODE_BLOCK_")) return "code";
  if (/^\d+[.)][\t ]+/.test(trimmed)) return "ordered";
  if (/^[-+*][\t ]+/.test(trimmed)) return "unordered";
  if (/^>+[\t ]?/.test(trimmed)) return "quote";
  if (/^#{1,6}[\t ]+/.test(trimmed)) return "heading";
  return null;
}

function protectedTokenMatch(
  text: string,
  kind: ProtectedTokenKind,
  index: number
): { start: number; end: number } | null {
  const match = protectedTokenPattern(kind, index).exec(text);
  return match
    ? { start: match.index, end: match.index + match[0].length }
    : null;
}

function insertMissingCodeBlockSentinels(
  text: string,
  missing: Array<{ index: number; sentinel: string }>,
  slots: ProtectedCodeBlockSlot[]
): string {
  let result = text;
  for (const item of missing) {
    const slot = slots[item.index];
    const previous = slot?.beforeParagraphBreaks
      ? protectedTokenMatch(
          result,
          "PARAGRAPH_BREAK",
          slot.beforeParagraphBreaks
        )
      : null;
    const next = slot?.afterParagraphBreaks
      ? protectedTokenMatch(
          result,
          "PARAGRAPH_BREAK",
          slot.afterParagraphBreaks
        )
      : null;
    if (next) {
      result = `${result.slice(0, next.start)}${item.sentinel}${result.slice(next.start)}`;
      continue;
    }
    if (previous) {
      result = `${result.slice(0, previous.end)}${item.sentinel}${result.slice(previous.end)}`;
      continue;
    }

    // Preserve the code block even when the model also dropped its break tokens.
    const lines = result.split("\n");
    const lineIndex = Math.min(
      Math.max(0, slot?.lineIndex ?? lines.length),
      lines.length
    );
    lines.splice(lineIndex, 0, item.sentinel, "");
    result = lines.join("\n");
  }
  return result;
}

function stripInventedListMarkers(
  text: string,
  sourceLineMarkers: SourceLineMarker[]
): string {
  if (sourceLineMarkers.length < 2) return text;
  const lines = text.split("\n");
  const ordered = lines.map((line, index) => {
    if (sourceLineMarkers[index] === undefined || line.includes("\uE000")) {
      return null;
    }
    const match = line.match(/^(\s*)(\d+)[.)][\t ]+/);
    return match
      ? {
          index,
          number: Number(match[2]),
          sourceMarker: sourceLineMarkers[index]
        }
      : null;
  });
  const unordered = lines.map((line, index) => {
    if (sourceLineMarkers[index] === undefined || line.includes("\uE000")) {
      return null;
    }
    const match = line.match(/^(\s*)([-+*])[\t ]+/);
    return match
      ? { index, marker: match[2], sourceMarker: sourceLineMarkers[index] }
      : null;
  });
  const remove = new Set<number>();
  let orderedRun: NonNullable<(typeof ordered)[number]>[] = [];
  for (const marker of ordered) {
    if (!marker) continue;
    const previous = orderedRun.at(-1);
    if (!previous || marker.number !== previous.number + 1) {
      orderedRun = [marker];
    } else {
      orderedRun.push(marker);
    }
    if (orderedRun.length >= 2 && orderedRun[0].number <= 1) {
      orderedRun.forEach((item) => {
        if (item.sourceMarker !== "ordered") remove.add(item.index);
      });
    }
  }
  let unorderedRun: NonNullable<(typeof unordered)[number]>[] = [];
  for (const marker of unordered) {
    if (!marker) continue;
    const previous = unorderedRun.at(-1);
    if (!previous || marker.marker !== previous.marker) {
      unorderedRun = [marker];
    } else {
      unorderedRun.push(marker);
    }
    if (unorderedRun.length >= 2) {
      unorderedRun.forEach((item) => {
        if (item.sourceMarker !== "unordered") remove.add(item.index);
      });
    }
  }
  return lines
    .map((line, index) =>
      remove.has(index)
        ? line.replace(/^\s*(?:\d+[.)]|[-+*])[\t ]+/, "")
        : line
    )
    .join("\n");
}

export function restoreTranslationText(
  text: string,
  protection: Pick<ProtectedTranslationText, "citations" | "paragraphBreaks"> &
    Partial<
      Pick<
        ProtectedTranslationText,
        | "links"
        | "formats"
        | "htmlTags"
        | "codeBlocks"
        | "codeBlockSlots"
        | "sourceLineMarkers"
      >
    >,
  options: { streaming?: boolean } = {}
): string {
  const visibleText = options.streaming
    ? stripIncompleteProtectedTokenSuffix(text)
    : text;
  let restored = stripCitationExplanationNoise(
    visibleText,
    protection.citations.length
  );
  protection.citations.forEach((marker, index) => {
    restored = restored.replace(
      protectedTokenPattern("CITATION", index + 1),
      marker
    );
  });
  (protection.links ?? []).forEach((link, index) => {
    const linkPattern = new RegExp(
      [
        protectedTokenSource("LINK_START", index + 1),
        "([\\s\\S]*?)",
        protectedTokenSource("LINK_END", index + 1)
      ].join(""),
      "gi"
    );
    restored = restored.replace(linkPattern, (_match, label: string) => {
      const visibleText = label.replace(/\s+/g, " ").trim() || link.text;
      return `[${visibleText.replace(/([\\\]])/g, "\\$1")}](<${link.href}>)`;
    });
    restored = restored
      .replace(protectedTokenPattern("LINK_START", index + 1), "")
      .replace(protectedTokenPattern("LINK_END", index + 1), "");
  });
  (protection.formats ?? []).forEach((format, index) => {
    const formatPattern = new RegExp(
      [
        protectedTokenSource("FORMAT_START", index + 1),
        "([\\s\\S]*?)",
        protectedTokenSource("FORMAT_END", index + 1)
      ].join(""),
      "gi"
    );
    restored = restored.replace(formatPattern, (_match, value: string) => {
      const visibleText = value.replace(/\s+/g, " ").trim() || format.text;
      return `<${format.tag}>${visibleText}</${format.tag}>`;
    });
    restored = restored
      .replace(protectedTokenPattern("FORMAT_START", index + 1), "")
      .replace(protectedTokenPattern("FORMAT_END", index + 1), "");
  });
  (protection.htmlTags ?? []).forEach((tag, index) => {
    restored = restored.replace(
      protectedTokenPattern("HTML_TAG", index + 1),
      tag
    );
  });
  const codeBlockSentinels: Array<{ sentinel: string; code: string }> = [];
  const missingCodeBlocks: Array<{ index: number; sentinel: string }> = [];
  (protection.codeBlocks ?? []).forEach((code, index) => {
    if (!code) return;
    const sentinel = `\uE000${index}\uE001`;
    const pattern = protectedTokenPattern("CODE_BLOCK", index + 1);
    let matched = false;
    restored = restored.replace(pattern, () => {
      matched = true;
      return sentinel;
    });
    if (matched) {
      codeBlockSentinels.push({ sentinel, code });
    } else if (!options.streaming) {
      missingCodeBlocks.push({ index, sentinel });
    }
  });
  if (!options.streaming && missingCodeBlocks.length) {
    restored = insertMissingCodeBlockSentinels(
      restored,
      missingCodeBlocks,
      protection.codeBlockSlots ?? []
    );
    missingCodeBlocks.forEach(({ index, sentinel }) => {
      const code = protection.codeBlocks?.[index];
      if (code) codeBlockSentinels.push({ sentinel, code });
    });
  }
  protection.paragraphBreaks.forEach((separator, index) => {
    restored = restored.replace(
      protectedTokenPattern("PARAGRAPH_BREAK", index + 1),
      separator.includes("\n\n") ? "\n\n" : separator
    );
  });
  restored = stripInventedListMarkers(
    restored,
    protection.sourceLineMarkers ?? []
  );
  const missingCitations = protection.citations.filter(
    (marker) => marker && !restored.includes(marker)
  );
  if (!options.streaming && missingCitations.length) {
    restored = `${restored.trimEnd()} ${missingCitations.join(" ")}`;
  }
  restored = stripCitationMarkerExplanationNoise(restored, protection.citations);
  restored = stripBrokenTranslationPlaceholderFragments(restored);
  restored = stripTranslationTaskPreface(restored);
  restored = restored.replace(/\n[\t ]*\n(?:[\t ]*\n)+/g, "\n\n");
  for (const { sentinel, code } of codeBlockSentinels) {
    restored = restored.split(sentinel).join(code);
  }
  return restored;
}

const DICTIONARY_FIELD_LABEL =
  /[\t ]*(?:[;；|][\t ]*)?(?:\n[\t ]*)?(\*\*(?:释义|釋義|义项|義項|语域|語域|搭配|变体|變體|助记|助記|例句|Definition|Senses|Register|Collocations|Variants|Mnemonic|Examples|Definición|Acepciones|Registro|Colocaciones|Variantes|Mnemotecnia|Ejemplos|Définition|Sens|Registre|Mnémotechnique|Exemples|Bedeutungen|Kollokationen|Varianten|Merksatz|Beispiele|Definizione|Accezioni|Collocazioni|Varianti|Mnemonico|Esempi)[：:]?\*\*)/g;

export function normalizeDictionaryTranslationMarkdown(text: string): string {
  const normalized = text.replace(/\r\n?/g, "\n").trim();
  if (!normalized) return normalized;

  return normalized
    .replace(
      DICTIONARY_FIELD_LABEL,
      (match, label: string, offset: number, source: string) => {
        const before = source.slice(0, offset);
        if (!before || /\n[\t ]*$/.test(before)) return match;
        return `\n\n${label}`;
      }
    )
    .replace(/\n[\t ]*\n(?:[\t ]*\n)+/g, "\n\n");
}

export function buildProtectedTranslationPrompt(
  config: PromptConfigSource | undefined,
  sourceText: string,
  protectedText: string,
  options: { dictionaryForShortInput?: boolean } = {}
): string {
  return [
    buildProtectedTranslationInstruction(config, sourceText, options),
    buildProtectedTranslationInput(protectedText)
  ].filter(Boolean).join("\n");
}

export function buildProtectedTranslationInstruction(
  config: PromptConfigSource | undefined,
  sourceText: string,
  options: { dictionaryForShortInput?: boolean } = {}
): string {
  const dictionaryMode =
    options.dictionaryForShortInput && isDictionaryTranslationInput(sourceText);
  return [
    dictionaryMode
      ? dictionaryTranslationInstruction(config, sourceText)
      : autoTranslateInstruction(config, sourceText),
    translationDirectionInstruction(config, sourceText),
    dictionaryMode ? "" : translationFormatInstruction(config),
    dictionaryMode ? "" : translationStructureIntegrityInstruction(),
    dictionaryMode ? "" : htmlFormattingInstruction(config),
    dictionaryMode
      ? ""
      : uiText(
          typeof config === "object" ? config?.interfaceLanguage : config,
          "translationOutputOnlyInstruction"
        )
  ].filter(Boolean).join("\n");
}

export function buildProtectedTranslationInput(protectedText: string): string {
  return [
    "<translation-input>",
    protectedText,
    "</translation-input>"
  ].filter(Boolean).join("\n");
}

export function buildPageTranslationSystemPrompt(
  config: PromptConfigSource | undefined,
  sourceText: string
): string {
  return [
    autoTranslateInstruction(config, sourceText),
    translationDirectionInstruction(config, sourceText),
    translationFormatInstruction(config),
    translationStructureIntegrityInstruction(),
    htmlFormattingInstruction(config),
    uiText(
      typeof config === "object" ? config?.interfaceLanguage : config,
      "jsonArrayTranslationInstruction"
    ),
    uiText(
      typeof config === "object" ? config?.interfaceLanguage : config,
      "citationPlaceholderInstruction"
    ),
    uiText(
      typeof config === "object" ? config?.interfaceLanguage : config,
      "jsonArrayReturnInstruction"
    )
  ].filter(Boolean).join("\n");
}

export function buildPageTranslationUserPrompt(
  blocks: PageTextBlock[]
): string {
  return `<translation-input>\n${JSON.stringify(blocks)}\n</translation-input>`;
}

export function createMessage(
  role: ChatMessage["role"],
  content: string,
  partial: Partial<ChatMessage> = {}
): ChatMessage {
  return {
    id: crypto.randomUUID(),
    role,
    content,
    createdAt: Date.now(),
    ...partial
  };
}

export function toModelMessage(message: ChatMessage): ChatMessage {
  const { modelContent, ...visibleMessage } = message;
  return modelContent
    ? { ...visibleMessage, content: modelContent }
    : visibleMessage;
}

export function truncateText(
  text: string,
  maxChars: number,
  language?: AppLanguage
): string {
  const normalized = text.replace(/\u0000/g, "").trim();
  if (normalized.length <= maxChars) return normalized;
  const head = Math.floor(maxChars * 0.72);
  const tail = maxChars - head;
  return `${normalized.slice(0, head)}\n\n[...${uiText(language, "contentTruncated")}...]\n\n${normalized.slice(-tail)}`;
}

export function isPointInsideAnyRect(
  rects: ArrayLike<
    Pick<DOMRect, "left" | "right" | "top" | "bottom" | "width" | "height">
  >,
  clientX: number,
  clientY: number
): boolean {
  return Array.from(rects).some(
    (rect) =>
      rect.width !== 0 &&
      rect.height !== 0 &&
      clientX >= rect.left &&
      clientX <= rect.right &&
      clientY >= rect.top &&
      clientY <= rect.bottom
  );
}

export function cleanBaseUrl(url: string): string {
  return url.trim().replace(/\/+$/, "");
}

export function endpointUrl(baseUrl: string, suffix: string): string {
  const base = cleanBaseUrl(baseUrl);
  if (base.endsWith(suffix)) return base;
  return `${base}${suffix}`;
}

export function originPattern(url: string): string | null {
  try {
    const parsed = new URL(url);
    if (!["http:", "https:"].includes(parsed.protocol)) return null;
    return `${parsed.origin}/*`;
  } catch {
    return null;
  }
}

export function parseCustomHeaders(
  raw: string,
  language?: AppLanguage
): Record<string, string> {
  if (!raw.trim()) return {};
  const value: unknown = JSON.parse(raw);
  if (!value || Array.isArray(value) || typeof value !== "object") {
    throw new Error(uiText(language, "customHeadersJsonObject"));
  }
  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [key, String(entry)])
  );
}

export function extractJsonArray<T = unknown>(
  text: string,
  language?: AppLanguage
): T[] {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  const source = fenced ?? text;
  const start = source.indexOf("[");
  const end = source.lastIndexOf("]");
  if (start < 0 || end <= start) {
    throw new Error(uiText(language, "jsonArrayMissing"));
  }
  const parsed: unknown = JSON.parse(source.slice(start, end + 1));
  if (!Array.isArray(parsed)) {
    throw new Error(uiText(language, "jsonArrayInvalid"));
  }
  return parsed as T[];
}

function extractLooseObjectChunks(source: string): string[] {
  const chunks: string[] = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    if (start < 0) {
      if (char === "{") {
        start = index;
        depth = 1;
        inString = false;
        escaped = false;
      }
      continue;
    }
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === "\"") {
        inString = false;
      }
      continue;
    }
    if (char === "\"") {
      inString = true;
      continue;
    }
    if (char === "{") {
      depth += 1;
      continue;
    }
    if (char === "}") {
      depth -= 1;
      if (depth === 0) {
        chunks.push(source.slice(start, index + 1));
        start = -1;
      }
    }
  }
  return chunks;
}

function parseLooseTranslationChunk(chunk: string): unknown | null {
  try {
    return JSON.parse(chunk);
  } catch {
    const fields = ["id", "text", "translation", "translatedText", "content"];
    const record: Record<string, unknown> = {};
    for (const field of fields) {
      const match = chunk.match(
        new RegExp(
          `"(?:${field})"\\s*:\\s*"((?:\\\\.|[^"])*)"`,
          "i"
        )
      );
      if (match?.[1]) {
        try {
          record[field] = JSON.parse(`"${match[1]}"`);
        } catch {
          record[field] = match[1];
        }
      }
    }
    return Object.keys(record).length ? record : null;
  }
}

export function extractPageTranslationEntries(
  text: string,
  expectedCount: number,
  language?: AppLanguage
): unknown[] {
  try {
    return extractJsonArray(text, language);
  } catch (arrayError) {
    const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
    const source = (fenced ?? text).trim();
    try {
      const parsed = JSON.parse(source) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const record = parsed as Record<string, unknown>;
        for (const key of ["translations", "items", "results", "data"]) {
          if (Array.isArray(record[key])) return record[key] as unknown[];
        }
        if (expectedCount === 1) return [record];
      }
    } catch {
      // A single translated paragraph may legitimately be returned as plain text.
    }
    const looseChunks = extractLooseObjectChunks(source)
      .map((chunk) => parseLooseTranslationChunk(chunk))
      .filter((entry): entry is object => Boolean(entry));
    if (looseChunks.length) return looseChunks;
    if (expectedCount === 1 && source && !/^[\[{]/.test(source)) {
      return [{ text: source }];
    }
    throw arrayError;
  }
}

/**
 * Models occasionally rewrite opaque block IDs or return a different field
 * name for the translated text. Keep the page's request order as the final
 * fallback so a valid translation is not discarded during DOM write-back.
 */
export function alignPageTranslations(
  blocks: PageTextBlock[],
  entries: unknown[]
): PageTranslation[] {
  const candidates = entries.flatMap((entry) => {
    if (typeof entry === "string" && entry.trim()) {
      return [{ id: "", text: entry.trim() }];
    }
    if (!entry || typeof entry !== "object") return [];
    const record = entry as Record<string, unknown>;
    const text = [record.text, record.translation, record.translatedText, record.content]
      .find(
        (value): value is string =>
          Boolean(typeof value === "string" && value.trim())
      );
    if (!text) return [];
    return [{
      id: typeof record.id === "string" ? record.id : "",
      text: text.trim()
    }];
  });
  const used = new Set<number>();
  const alignedByBlockId = new Map<string, PageTranslation>();

  for (const block of blocks) {
    const candidateIndex = candidates.findIndex(
      (candidate, entryIndex) =>
        !used.has(entryIndex) && candidate.id.trim() === block.id
    );
    if (candidateIndex < 0) continue;
    used.add(candidateIndex);
    alignedByBlockId.set(block.id, {
      id: block.id,
      text: candidates[candidateIndex].text
    });
  }

  for (const [index, block] of blocks.entries()) {
    if (alignedByBlockId.has(block.id)) continue;
    let candidateIndex = -1;
    if (candidateIndex < 0 && !used.has(index) && candidates[index]) {
      candidateIndex = index;
    }
    if (candidateIndex < 0) {
      candidateIndex = candidates.findIndex((_, entryIndex) => !used.has(entryIndex));
    }
    if (candidateIndex < 0) continue;
    used.add(candidateIndex);
    alignedByBlockId.set(block.id, {
      id: block.id,
      text: candidates[candidateIndex].text
    });
  }
  return blocks.flatMap((block) => {
    const translation = alignedByBlockId.get(block.id);
    return translation ? [translation] : [];
  });
}

export function dataUrlParts(dataUrl: string, language?: AppLanguage): {
  mimeType: string;
  base64: string;
} {
  const match = dataUrl.match(/^data:([^;,]+);base64,(.+)$/);
  if (!match) throw new Error(uiText(language, "invalidImageData"));
  return { mimeType: match[1], base64: match[2] };
}

export function shortTitle(text: string, max = 42): string {
  const singleLine = text.replace(/\s+/g, " ").trim();
  return singleLine.length <= max
    ? singleLine
    : `${singleLine.slice(0, max - 1)}…`;
}

export function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
